// FILE: observable-vs-promise.ts
import { Observable, firstValueFrom } from 'rxjs';

type Shipment = Readonly<{ id: string; status: 'in-transit' | 'delivered' }>;
let executions = 0;

// Cold and synchronous for demonstration; a real HTTP request is async.
const shipment$ = new Observable<Shipment>(subscriber => {
  executions += 1;
  subscriber.next({ id: 'DEMO-1', status: 'in-transit' });
  subscriber.complete();
});

shipment$.subscribe(value => console.log('subscriber A', value));
shipment$.subscribe(value => console.log('subscriber B', value));
console.log('executions', executions); // 2 independent executions

async function oneValue(): Promise<Shipment> {
  return firstValueFrom(shipment$); // subscribes and resolves on first value
}
oneValue().then(value => console.log('promise result', value));

