import { BehaviorSubject } from 'rxjs';

type Workspace = Readonly<{ id: string; label: string }>;

export class WorkspaceState {
  private readonly selectedSubject = new BehaviorSubject<Workspace | null>(null);
  readonly selected$ = this.selectedSubject.asObservable();

  select(workspace: Workspace | null): void {
    this.selectedSubject.next(workspace);
  }

  snapshot(): Workspace | null {
    return this.selectedSubject.getValue();
  }
}

const state = new WorkspaceState();
const first = state.selected$.subscribe(value => console.log('first', value?.id ?? 'none'));
state.select({ id: 'DEMO-A', label: 'Practice tenant' });
const late = state.selected$.subscribe(value => console.log('late', value?.id ?? 'none'));
first.unsubscribe();
late.unsubscribe();

// FILE: order-operators.ts
import { from, filter, map, tap } from 'rxjs';

type Order = Readonly<{ id: string; status: 'paid' | 'pending'; totalMinor: number }>;
const orders: readonly Order[] = [
  { id: 'A', status: 'paid', totalMinor: 1200 },
  { id: 'B', status: 'pending', totalMinor: 750 },
  { id: 'C', status: 'paid', totalMinor: 450 }
];

const paidLabels$ = from(orders).pipe(
  filter(order => order.status === 'paid'),
  map(order => `${order.id}: ${order.totalMinor} minor units`),
  tap(label => console.log('processed', label))
);

paidLabels$.subscribe(label => console.log('visible', label));
// visible: A and C; B is filtered out.

// FILE: cart-summary.component.ts
import { Component, computed, signal } from '@angular/core';

type LineItem = Readonly<{ sku: string; quantity: number; unitPriceMinor: number }>;

@Component({
  selector: 'app-cart-summary',
  standalone: true,
  template: `
    <h2>Demo cart</h2>
    <p>Units: {{ itemCount() }}</p>
    <p>Subtotal (minor units): {{ subtotalMinor() }}</p>
    <button (click)="addOne()">Add one sample item</button>
  `
})
export class CartSummaryComponent {
  readonly items = signal<readonly LineItem[]>([
    { sku: 'BOOK-1', quantity: 1, unitPriceMinor: 1250 }
  ]);
  readonly itemCount = computed(() =>
    this.items().reduce((sum, item) => sum + item.quantity, 0)
  );
  readonly subtotalMinor = computed(() =>
    this.items().reduce((sum, item) => sum + item.quantity * item.unitPriceMinor, 0)
  );

  addOne(): void {
    this.items.update(items => items.map(item =>
      item.sku === 'BOOK-1' ? { ...item, quantity: item.quantity + 1 } : item
    ));
  }
}

