import { AsyncPipe } from '@angular/common';
import { Component, inject, Injectable } from '@angular/core';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { catchError, debounceTime, distinctUntilChanged, map, of, startWith, switchMap } from 'rxjs';

interface Product { readonly id: string; readonly name: string; }

@Injectable({ providedIn: 'root' })
export class ProductSearchService {
  private readonly products: readonly Product[] = [
    { id: '1', name: 'Bookstand' }, { id: '2', name: 'Notebook' },
    { id: '3', name: 'Desk lamp' }
  ];

  search(term: string) {
    // Replace this mock with HttpClient.get<Product[]>(...) in production.
    return of(this.products.filter(p => p.name.toLowerCase().includes(term)));
  }
}

@Component({
  selector: 'app-product-search', standalone: true,
  imports: [ReactiveFormsModule, AsyncPipe],
  template: `
    <label for="query">Find products</label>
    <input id="query" type="search" [formControl]="query" />
    @if (results$ | async; as results) {
      @if (results.length === 0) { <p>No matching products</p> }
      <ul>
        @for (product of results; track product.id) {
          <li>{{ product.name }}</li>
        }
      </ul>
    }
  `
})
export class ProductSearchComponent {
  private readonly api = inject(ProductSearchService);
  readonly query = new FormControl('', { nonNullable: true });
  readonly results$ = this.query.valueChanges.pipe(
    startWith(this.query.value),
    map(value => value.trim().toLowerCase()),
    debounceTime(300),
    distinctUntilChanged(),
    switchMap(term => this.api.search(term).pipe(
      catchError(error => {
        console.error('Search failed', error);
        return of([] as Product[]);
      })
    ))
  );
}
